// Bounded Sampler — runs once for all items.
// Turns the loaded JSON file into one item per session and builds a bounded
// sample for the classifier: first 40 turns + last 20 turns (whole call if shorter).
const FIRST_N = 40;
const LAST_N = 20;

// The file-extraction node may emit the whole array, one item per session, or wrap it in `data`.
const sessions = $input
  .all()
  .flatMap(({ json }) => {
    if (Array.isArray(json.data)) return json.data;
    if (json.data && Array.isArray(json.data.transcript)) return [json.data];
    return [json];
  })
  .filter((s) => s && Array.isArray(s.transcript));

const fmt = (t) => `[${t.timestamp}] ${t.speaker}: ${t.text}`;

return sessions.map((s) => {
  const turns = s.transcript;
  const isBounded = turns.length > FIRST_N + LAST_N;
  const head = turns.slice(0, FIRST_N);
  const tail = isBounded ? turns.slice(-LAST_N) : turns.slice(FIRST_N);

  const sampleText = [
    ...head.map(fmt),
    ...(isBounded ? ['[... middle of the call omitted ...]'] : []),
    ...tail.map(fmt),
  ].join('\n');

  const participants = s.participants ?? [];
  return {
    json: {
      session_id: s.id,
      title: s.title,
      session_date: s.created_at,
      participants,
      // The coach is the team member; everyone else is the client.
      coach_names: participants.filter((p) => p.is_team_member).map((p) => p.name),
      client_names: participants.filter((p) => !p.is_team_member).map((p) => p.name),
      total_turns: turns.length,
      sampled_turns: head.length + tail.length,
      sample_text: sampleText,
      transcript: turns,
    },
  };
});

// Parse Classification — runs once for all items.
// Turns the raw LLM reply into a validated {meeting_type, confidence_score, summary}
// and NEVER throws: any malformed / missing / failed reply degrades to
// "Other" @ 0.0 so the Ingestion Gate safely rejects it.
const MEETING_TYPES = ['Client Coaching', 'Internal Operations', 'Sales Discovery', 'Other'];

function extractJson(raw) {
  if (raw && typeof raw === 'object') return raw;
  if (typeof raw !== 'string') return null;
  const cleaned = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/```\s*$/, '')
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const braces = cleaned.match(/\{[\s\S]*\}/); // JSON buried in prose
    if (braces) {
      try {
        return JSON.parse(braces[0]);
      } catch (e2) {
        /* fall through */
      }
    }
  }
  return null;
}

return $input.all().map((item, i) => {
  const session = $('Sampler').itemMatching(i).json;
  const parsed = extractJson(item.json?.message?.content);

  let meetingType = 'Other';
  let confidence = 0;
  let summary = '';
  let issue = null;

  if (item.json?.error) {
    issue = 'classifier_call_failed';
  } else if (!parsed) {
    issue = 'unparseable_classifier_output';
  } else {
    const match = MEETING_TYPES.find(
      (t) => t.toLowerCase() === String(parsed.meeting_type ?? '').trim().toLowerCase(),
    );
    meetingType = match ?? 'Other';
    const c = Number(parsed.confidence_score);
    confidence = Number.isFinite(c) ? Math.min(1, Math.max(0, c)) : 0;
    summary = String(parsed.summary ?? '').trim();
    if (!match) issue = 'unknown_meeting_type';
    if (!Number.isFinite(c)) issue = 'invalid_confidence_score';
  }

  let rejectReason = null;
  if (issue) rejectReason = issue;
  else if (meetingType !== 'Client Coaching') rejectReason = `classified_as_${meetingType.toLowerCase().replace(/\s+/g, '_')}`;
  else if (confidence < 0.8) rejectReason = 'low_confidence_coaching';

  return {
    json: {
      ...session,
      meeting_type: meetingType,
      confidence_score: confidence,
      summary,
      classifier_issue: issue,
      reject_reason: rejectReason,
    },
  };
});

// Dual-Stream Parser — runs once for all items (one input item per approved session).
//   Stream 1 "framework"    : dense conceptual takeaways (distilled by the LLM upstream, with a heuristic fallback)
//   Stream 2 "voice_sample" : the coach's verbatim turns only, packed into 400-700 character chunks
// Emits one item per chunk, ready to be embedded.
const MIN_CHARS = 400;
const MAX_CHARS = 700;

// ---- helpers ---------------------------------------------------------------
const normalize = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

function splitSentences(text) {
  return text.match(/[^.!?]+(?:[.!?]+["')\]]*|$)/g)?.map((s) => s.trim()).filter(Boolean) ?? [text];
}

// A single sentence longer than MAX_CHARS is wrapped on word boundaries.
function hardWrap(sentence) {
  if (sentence.length <= MAX_CHARS) return [sentence];
  const out = [];
  let cur = '';
  for (const word of sentence.split(' ')) {
    if ((cur + ' ' + word).trim().length > MAX_CHARS) {
      out.push(cur);
      cur = word;
    } else {
      cur = (cur + ' ' + word).trim();
    }
  }
  if (cur) out.push(cur);
  return out;
}

const render = (units) =>
  units.reduce((acc, u, i) => (i === 0 ? u.text : acc + (u.newTurn ? '\n' : ' ') + u.text), '');

// Greedy-pack sentence units into <= MAX_CHARS groups, then rebalance a short tail.
function packChunks(units) {
  const groups = [];
  let cur = [];
  for (const u of units) {
    if (cur.length && render([...cur, u]).length > MAX_CHARS) {
      groups.push(cur);
      cur = [u];
    } else {
      cur.push(u);
    }
  }
  if (cur.length) groups.push(cur);

  // Short last chunk: borrow trailing sentences from the previous chunk while both stay valid.
  while (groups.length > 1) {
    const last = groups[groups.length - 1];
    const prev = groups[groups.length - 2];
    if (render(last).length >= MIN_CHARS) break;
    if (render([...prev, ...last]).length <= MAX_CHARS) {
      groups.splice(-2, 2, [...prev, ...last]);
      continue;
    }
    const moved = prev[prev.length - 1];
    if (prev.length > 1 && render(prev.slice(0, -1)).length >= MIN_CHARS && render([moved, ...last]).length <= MAX_CHARS) {
      prev.pop();
      last.unshift(moved);
    } else {
      break;
    }
  }
  return groups.map(render);
}

// ---- main ------------------------------------------------------------------
const out = [];

$input.all().forEach((item, i) => {
  const session = $('Ingestion Gate').itemMatching(i).json;
  const coaches = new Set(session.coach_names);
  const coachTurns = session.transcript.filter((t) => coaches.has(t.speaker));
  const base = {
    title: session.title,
    session_date: session.session_date,
    coach: session.coach_names.join(', '),
    client: session.client_names.join(', '),
    meeting_type: session.meeting_type,
    confidence_score: session.confidence_score,
  };

  // Stream 2: voice samples (verbatim coach dialogue only — no timestamps, no speaker labels, no client turns)
  const units = coachTurns.flatMap((t) =>
    splitSentences(normalize(t.text))
      .flatMap(hardWrap)
      .map((text, idx) => ({ text, newTurn: idx === 0 })),
  );
  const voice = packChunks(units);

  // Stream 1: frameworks (LLM-distilled; heuristic fallback if the reply is unusable)
  let frameworks = [];
  try {
    const parsed = JSON.parse(item.json?.message?.content ?? '');
    frameworks = (parsed.frameworks ?? [])
      .map((f) => ({ name: normalize(f.name), takeaway: normalize(f.takeaway) }))
      .filter((f) => f.name && f.takeaway.length > 40)
      .slice(0, 3);
  } catch (e) {
    /* handled by fallback below */
  }
  let frameworkSource = 'llm_distilled';
  if (!frameworks.length) {
    frameworkSource = 'heuristic_fallback';
    const cue = /framework|test|criteria|diagnos|principle|system|architecture/i;
    const picked = coachTurns.map((t) => normalize(t.text)).filter((t) => cue.test(t));
    frameworks = [
      { name: 'Coaching framework (auto-extracted)', takeaway: (picked.join(' ') || voice.join(' ')).slice(0, 600) },
    ];
  }

  frameworks.forEach((f, idx) => {
    const content = `Framework: ${f.name}. ${f.takeaway}`;
    out.push({
      json: {
        session_id: session.session_id,
        stream_type: 'framework',
        content,
        metadata: { ...base, chunk_index: idx, char_count: content.length, framework_name: f.name, source: frameworkSource },
      },
    });
  });

  voice.forEach((content, idx) => {
    out.push({
      json: {
        session_id: session.session_id,
        stream_type: 'voice_sample',
        content,
        metadata: { ...base, chunk_index: idx, char_count: content.length, speaker: base.coach },
      },
    });
  });
});

return out;

// Prepare Row — merges each chunk with its embedding and serialises it for pgvector.
const EXPECTED_DIMS = 1024; // bge-m3; must match vector(1024) in init.sql

return $input.all().map((item, i) => {
  const chunk = $('Dual-Stream Parser').itemMatching(i).json;
  const vector = item.json?.embeddings?.[0];

  if (!Array.isArray(vector) || vector.length !== EXPECTED_DIMS) {
    throw new Error(
      `Embedding for ${chunk.session_id}/${chunk.stream_type} has ${vector?.length ?? 0} dims, expected ${EXPECTED_DIMS}`,
    );
  }

  return {
    json: {
      session_id: chunk.session_id,
      stream_type: chunk.stream_type,
      content: chunk.content,
      metadata: JSON.stringify(chunk.metadata),
      embedding: `[${vector.join(',')}]`, // pgvector text literal
    },
  };
});

// Ingestion Summary — one line per session with how many chunks were stored per stream.
const bySession = {};
for (const { json } of $input.all()) {
  const s = (bySession[json.session_id] ??= { framework: 0, voice_sample: 0 });
  s[json.stream_type] += 1;
}

return Object.entries(bySession).map(([session_id, counts]) => ({
  json: { session_id, status: 'ingested', ...counts, total_chunks: counts.framework + counts.voice_sample },
}));
